import { tv, type VariantProps } from "@/lib/beton/tv";

export const hero = tv({
  slots: {
    root: "relative isolate w-full overflow-hidden",
    inner: "mx-auto flex w-full max-w-7xl flex-col px-4 py-20 sm:px-6 lg:py-28",
    content: "flex flex-col gap-6",
    eyebrow:
      "w-fit border-3 border-border bg-secondary px-3 py-1 font-mono text-xs font-bold tracking-widest uppercase",
    title: "font-display text-h1 font-black tracking-tight text-balance text-foreground",
    description: "max-w-prose text-pretty text-lg text-foreground",
    actions: "flex flex-wrap items-center gap-4 pt-2",
    aside: "flex min-w-0 items-center justify-center",
    note: "font-mono text-xs font-bold",
  },
  variants: {
    variant: {
      stacked: { inner: "items-start gap-10" },
      split: { inner: "gap-12 lg:grid lg:grid-cols-2 lg:items-center" },
      poster: {
        inner: "items-center gap-8 text-center",
        content: "items-center",
        description: "mx-auto",
        actions: "justify-center",
        title: "uppercase",
      },
    },
    surface: {
      paper: { root: "bg-surface" },
      raised: { root: "bg-raised" },
      accent: { root: "bg-primary" },
      ink: { root: "bg-ink text-paper" },
    },
  },
  defaultVariants: {
    variant: "stacked",
    surface: "paper",
  },
});

export type HeroVariants = VariantProps<typeof hero>;

import { hero, type HeroVariants } from "@/lib/beton/recipes/hero.recipe";
import { useId, type ComponentProps, type ReactNode } from "react";

export interface HeroProps extends Omit<ComponentProps<"section">, "title">, HeroVariants {
  /** The one heading of the page. */
  title: ReactNode;
  /** A short line above the heading, such as a version or a category. */
  eyebrow?: ReactNode;
  /** The paragraph under the heading. */
  description?: ReactNode;
  /** Buttons under the text. */
  actions?: ReactNode;
  /** A line under the buttons: a licence, a size, a reassurance. */
  note?: ReactNode;
  /** What goes beside the text in the split layout: a panel, a picture, a demo. */
  aside?: ReactNode;
  /** Drawn behind everything, such as a grid or a halftone. */
  background?: ReactNode;
  /** The heading level. Defaults to h1: a hero is the top of a page. */
  headingLevel?: 1 | 2;
}

/** The top of a page: what this is, why it matters, and the way in. */
export function Hero({
  variant = "stacked",
  surface = "paper",
  title,
  eyebrow,
  description,
  actions,
  note,
  aside,
  background,
  headingLevel = 1,
  className,
  children,
  ...props
}: HeroProps) {
  const styles = hero({ variant, surface });
  const id = useId();
  const Heading = `h${headingLevel}` as const;

  return (
    <section
      {...props}
      aria-labelledby={`${id}-title`}
      data-variant={variant}
      className={styles.root({ class: className })}
    >
      {background}
      <div className={styles.inner()}>
        <div className={styles.content()}>
          {eyebrow ? <p className={styles.eyebrow()}>{eyebrow}</p> : null}
          <Heading id={`${id}-title`} className={styles.title()}>
            {title}
          </Heading>
          {description ? <p className={styles.description()}>{description}</p> : null}
          {actions ? <div className={styles.actions()}>{actions}</div> : null}
          {note ? <p className={styles.note()}>{note}</p> : null}
          {children}
        </div>
        {aside && variant === "split" ? <div className={styles.aside()}>{aside}</div> : null}
      </div>
    </section>
  );
}
